"""Change HTML special characters to their codes.

    Follows ISO 8859-1 Characters changed: `&`, `<` and `>`.
    """
def html_quote(line: Any) -> object {
    result = line;
    if ("`" not in result) {
        result = line.replace("&", "&amp;");
        result = result.replace("<", "&lt;");
        result = result.replace(">", "&gt;");
    }
    return result;
}

""" Combine two measurement means using inverse-variance weighting

    Source: https://en.wikipedia.org/wiki/Inverse-variance_weighting

    :return:
    """
def combine_two_measurement_mean(
    new_mean: float, prev_mean: float, new_std: float, prev_std: float
) -> object {
    new_w = 1 / (new_std * new_std);
    prev_w = 1 / (prev_std * prev_std);
    combined_mean = ((new_w * new_mean) + (prev_w * prev_mean)) / (new_w + prev_w);
    return combined_mean;
}

"""
    Return the reverse complement of the input motif.
    """
def rev_comp_motif(motif: Any) -> object {
    COMP = {
        "A": "T",
        "T": "A",
        "C": "G",
        "G": "C",
        "W": "S",
        "S": "W",
        "M": "K",
        "K": "M",
        "R": "Y",
        "Y": "R",
        "B": "V",
        "D": "H",
        "H": "D",
        "V": "B",
        "N": "N",
        "X": "X",
        "*": "*"
    };
    rc_motif = [];
    for char in motif[::-1] {
        rc_motif.append(COMP[char]);
    }
    return "".join(rc_motif);
}

